function libraryFor(url){try{const u=new URL(url);if(!/^https?:$/.test(u.protocol))return null;const host=u.hostname.toLowerCase().replace(/\.$/,'');let best=null,score=-1;for(const e of ICON_LIBRARY){for(const d of e.domains){if(host!==d&&(e.exactDomains||!host.endsWith('.'+d)))continue;if(e.paths&&!e.paths.some(p=>u.pathname===p.replace(/\/$/,'')||u.pathname.startsWith(p)))continue;const s=d.length*10000+(e.paths?Math.max(...e.paths.map(p=>p.length)):0);if(s>score){best=e;score=s;}}}return best;}catch{return null;}}
